import { test, expect } from '@playwright/test';

test.describe('Notification Count Reset', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display notification count when messages are unread', async ({ page }) => {
    // Verify initial notification count is displayed
    const notificationBadge = page.getByRole('button', { name: /notifications/i });
    await expect(notificationBadge).toBeVisible();

    // Check that notification count shows a number greater than 0
    const countText = await notificationBadge.textContent();
    const count = parseInt(countText || '0', 10);
    expect(count).toBeGreaterThan(0);
  });

  test('should reset notification count to zero after reading all messages', async ({ page }) => {
    // Open notifications panel
    const notificationBadge = page.getByRole('button', { name: /notifications/i });
    await notificationBadge.click();

    // Wait for notification panel to appear
    const notificationPanel = page.getByRole('region', { name: /notifications/i });
    await expect(notificationPanel).toBeVisible();

    // Get all unread messages and mark them as read
    const unreadMessages = page.getByRole('article', { name: /unread/i });
    const messageCount = await unreadMessages.count();

    // Click on each message to mark as read
    for (let i = 0; i < messageCount; i++) {
      const message = page.getByRole('article').nth(i);
      await message.click();
      await page.waitForTimeout(300);
    }

    // Close notification panel
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify notification count is now zero
    const updatedBadge = page.getByRole('button', { name: /notifications/i });
    const updatedCountText = await updatedBadge.textContent();
    const updatedCount = parseInt(updatedCountText || '0', 10);
    expect(updatedCount).toBe(0);
  });

  test('should show zero notification count when no unread messages exist', async ({ page }) => {
    // Open notifications panel
    const notificationBadge = page.getByRole('button', { name: /notifications/i });
    await notificationBadge.click();

    // Wait for notification panel
    const notificationPanel = page.getByRole('region', { name: /notifications/i });
    await expect(notificationPanel).toBeVisible();

    // Verify empty state message appears
    const emptyStateMessage = page.getByText(/no new messages/i);
    await expect(emptyStateMessage).toBeVisible();

    // Close panel
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify badge shows zero or is hidden
    const badge = page.getByRole('button', { name: /notifications/i });
    const badgeText = await badge.textContent();
    const badgeCount = parseInt(badgeText || '0', 10);
    expect(badgeCount).toBe(0);
  });
});
